property_tests.invariant_check:
result = compose_enriched_summary(summary=s, rejected_approaches=ra, gotchas=g, assumptions=a)
for entry in ra:
    assert f'Tried: {entry["approach"]} — rejected because: {entry["reason"]}' in result
for gotcha in g:
    assert f'Watch out: {gotcha}' in result
for assumption in a:
    assert f'Assumes: {assumption}' in result
